(function(){'use strict';
/* Forestry Database generator — jahdb-forestry-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-FORESTRY-';
var SRC='public';
var RECORD_KIND='forestry record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Forest Ecology Basics","brief":"How forests work as living systems — energy, nutrients, and species woven together.","points":["Forests are ecosystems where trees dominate: producers capture sunlight, and every other organism depends on that energy.","Nutrient cycles move carbon, nitrogen, and phosphorus between soil, trees, and decomposers in closed loops.","Disturbance — fire, wind, insects — is natural and resets forest development in patches.","Biodiversity rises with structural variety: mixed ages, dead wood, and canopy gaps support more species."],"examples":["A fallen log hosting fungi, insects, salamanders, and seedlings at once.","A windthrow gap filling with saplings within two growing seasons."],"history":["Early 1900s: Clements' succession theory shaped forestry thinking for decades.","1970s-80s: ecosystem management replaced single-species timber focus in public forestry."],"uses":["Forest managers design harvests that mimic natural disturbance patterns.","Conservation planners protect ecological processes, not just species lists.","Students learn systems thinking through forest ecology."],"qa":[["What is a forest ecosystem?","Trees plus soil, water, wildlife, and microbes interacting as one system."],["Why does dead wood matter?","It feeds fungi and insects, stores carbon, and shelters wildlife."],["How do forests affect climate?","They store carbon, release moisture, and cool the air through transpiration."]]},{"title":"Silviculture","brief":"The art and science of growing forests — tending stands from seedling to harvest.","points":["Silviculture controls stand composition, structure, and growth through planned interventions.","Regeneration methods: even-aged (clearcut, shelterwood, seed-tree) or uneven-aged (selection) systems.","Intermediate treatments — thinning, pruning, release — focus growth on the best trees.","Prescriptions are written per stand: species, site quality, and owner goals drive every decision."],"examples":["A shelterwood cut leaving seed trees to naturally regenerate oak.","A precommercial thinning doubling the growth rate of crop pines."],"history":["1890s-1910s: German silvicultural systems imported to American forestry schools.","1960s-70s: intensive plantation silviculture rose with industrial timber demand."],"uses":["Timber companies grow predictable, high-yield wood supplies.","Public agencies balance timber with wildlife and recreation goals.","Consulting foresters write prescriptions for private landowners."],"qa":[["Even-aged vs uneven-aged?","Even-aged: one age class per stand. Uneven-aged: mixed ages via selection harvests."],["What is a shelterwood?","Gradual overstory removal that shelters new seedlings until established."],["Why thin a forest?","Less competition means faster growth on the remaining, most valuable trees."]]},{"title":"Timber Harvesting Methods","brief":"Getting wood out of the forest — systems matched to terrain, stand, and goals.","points":["Ground-based skidding suits gentle terrain; cable yarding works steep slopes; helicopters serve sensitive sites.","Cut-to-length systems process trees at the stump; whole-tree systems yard stems to the landing.","Best management practices (BMPs) protect water: streamside buffers, water bars, and seasonal limits.","Logging plans specify skid trails, landings, and slash treatment before a single tree falls."],"examples":["A cable yarder lifting logs across a steep ravine without new roads.","A cut-to-length harvester delimbing and bucking a spruce in seconds."],"history":["Late 1800s: crosscut saws and horse skidding ruled the woods.","1950s-70s: chainsaws, skidders, and trucks mechanized logging; 1990s+: cut-to-length and BMPs."],"uses":["Loggers match equipment to terrain for safety and low impact.","Landowners earn income while meeting stewardship goals.","Regulators inspect BMP compliance on harvest sites."],"qa":[["What is a skidder?","A machine that drags (skids) logs from stump to landing."],["What is slash?","Branches, tops, and bark left after harvest — managed to reduce fire risk."],["Do harvests damage soil?","Poorly planned ones can; BMPs like designated trails limit compaction and erosion."]]},{"title":"Reforestation","brief":"Putting forests back — planting and seeding the next generation after harvest or disaster.","points":["Artificial regeneration (planting nursery seedlings) guarantees species and spacing; natural regeneration is cheaper where seed sources exist.","Site preparation — scarification, herbicide, or burning — gives seedlings a head start over competing vegetation.","Seedling survival depends on proper planting depth, root care, and matching species to site.","Stocking surveys at year 1, 3, and 5 confirm the new forest is established."],"examples":["Hand-planting 800 pine seedlings a day on a clearcut in spring.","Aerial seeding of a burned mountainside too steep to plant."],"history":["1930s: Civilian Conservation Corps planted billions of trees across America.","1970s+: industrial forestry made replanting standard practice after harvest."],"uses":["Timber companies secure their future wood supply.","Agencies restore forests after wildfire and mining.","Carbon programs fund reforestation for climate benefits."],"qa":[["Plant or let nature seed?","Plant for control and speed; natural regeneration where seed trees and conditions suit."],["How many seedlings per acre?","Typically 400-800 depending on species and region."],["When is a planting 'successful'?","When stocking surveys show enough free-to-grow trees, usually by year 3-5."]]},{"title":"Forest Fire Management","brief":"Living with fire — preventing disasters while using fire as a forest tool.","points":["The fire triangle: fuel, oxygen, heat — remove any leg and fire stops.","Fuel management (thinning, mastication, prescribed fire) reduces wildfire intensity.","Initial attack aims to catch fires small; large fires get managed for values at risk.","The wildland-urban interface (WUI) is where homes meet flammable vegetation — the highest-stakes zone."],"examples":["A fuel break stopping a crown fire from reaching a subdivision.","Firefighters burning out from a road to rob an advancing wildfire of fuel."],"history":["1910: the Big Burn forged a century of US fire suppression policy.","1970s-2000s: science swung back toward prescribed fire and managed wildfire."],"uses":["Agencies protect communities while restoring fire-adapted ecosystems.","Homeowners create defensible space around structures.","Insurers and planners map WUI risk."],"qa":[["Why not put out every fire?","Suppression lets fuels build up, making future fires worse in fire-adapted forests."],["What is defensible space?","Cleared, thinned vegetation around a home giving firefighters room to work."],["Crown fire vs ground fire?","Crown fires race through treetops; ground fires creep through surface fuels."]]},{"title":"Prescribed Burns","brief":"Fire on purpose — carefully planned burns that heal fire-adapted forests.","points":["Prescriptions specify weather windows: humidity, wind, temperature, and fuel moisture ranges.","Burn bosses write burn plans with objectives, ignition patterns, holding resources, and smoke management.","Low-intensity burns consume surface fuels while sparing mature trees and soil.","Fire-adapted species like longleaf pine and giant sequoia depend on regular fire."],"examples":["A spring burn in longleaf pine releasing wiregrass seeds and killing hardwood encroachment.","An Indigenous-led cultural burn restoring meadow and oak savanna."],"history":["Pre-colonial: Indigenous peoples burned millions of acres annually across North America.","1990s-2010s: prescribed fire science and training expanded after catastrophic wildfires."],"uses":["Land managers reduce hazardous fuels safely.","Wildlife biologists restore fire-dependent habitats.","Communities breathe easier with less wildfire smoke."],"qa":[["Is prescribed fire safe?","With trained crews, weather windows, and contingency plans, escape rates are very low."],["What is a burn boss?","The qualified leader legally responsible for planning and executing the burn."],["Does burning harm wildlife?","Well-timed burns briefly displace animals but create richer habitat afterward."]]},{"title":"Dendrology","brief":"Knowing trees by name — identification through leaves, bark, buds, and form.","points":["Leaves: arrangement (opposite/alternate), shape, margin, and venation narrow the field fast.","Winter ID uses buds, leaf scars, bark, and twig traits when leaves are gone.","Bark patterns — plates, furrows, scales — are often the quickest field clue on mature trees.","Range maps confirm: a tree can't be what doesn't grow there."],"examples":["Separating red oak from white oak by leaf lobe tips — pointed vs rounded.","Identifying shagbark hickory at fifty paces by its peeling bark strips."],"history":["1700s: Linnaeus gave trees the two-name system still in use.","1900s: field guides and dichotomous keys made ID accessible to foresters and the public."],"uses":["Foresters inventory species composition for management plans.","Arborists diagnose problems starting with correct identification.","Hikers and naturalists read the landscape through its trees."],"qa":[["Opposite or alternate?","Maples, ashes, dogwoods: opposite. Oaks, hickories, most others: alternate."],["Best beginner tree book?","A regional field guide with photos plus a simple key — start local."],["Can apps identify trees?","They help, but verify with bark, buds, and range — apps misidentify lookalikes."]]},{"title":"Forest Pathology","brief":"Tree diseases — diagnosing and managing the pathogens that kill forests.","points":["Root rots (Armillaria, Heterobasidion) spread tree-to-tree through root contact and soil.","Cankers girdle stems; wilts plug vascular tissue; rusts need alternate hosts to complete cycles.","Diagnosis follows the disease triangle: susceptible host + virulent pathogen + favorable environment.","Sanitation — removing infected trees and stumps — is the most reliable control in forests."],"examples":["Stump removal breaking an Annosum root-rot infection center in pine.","Pruning blister-rust cankers off white pine before they reach the trunk."],"history":["1904: chestnut blight arrived in New York; by 1950 it had functionally erased American chestnut.","1970s-90s: integrated disease management replaced reliance on chemicals alone."],"uses":["Forest health specialists survey and diagnose outbreaks.","Nurseries cull infected stock to stop spread at the source.","Breeders select resistant varieties like blight-resistant chestnut hybrids."],"qa":[["What is chestnut blight?","A fungal canker that killed ~4 billion American chestnuts in 40 years."],["Can diseased trees be saved?","Sometimes individually; at stand scale, removal and resistance are the tools."],["How do diseases spread?","Wind, water, insects, tools, and root contact — sanitation breaks the chain."]]},{"title":"Forest Entomology","brief":"Insects in the woods — pollinators, decomposers, and the outbreak pests that reshape forests.","points":["Bark beetles mass-attack stressed trees, overwhelming defenses with pheromone-coordinated assaults.","Defoliators (gypsy moth, spruce budworm) strip canopies; healthy trees usually refoliate, stressed ones die.","Most forest insects are beneficial: pollinators, predators of pests, and wood decomposers.","Outbreaks follow drought, overstocking, and warming — stressed forests invite epidemics."],"examples":["Pheromone traps catching thousands of bark beetles to monitor an outbreak's edge.","A parasitic wasp release checking an invasive defoliator without sprays."],"history":["1890s: gypsy moth introduced near Boston; it has defoliated millions of acres since.","2000s: mountain pine beetle killed vast lodgepole stands across western North America."],"uses":["Entomologists forecast outbreaks from trap and survey data.","Managers thin stressed stands to lower beetle susceptibility.","Biocontrol programs release predators against invasive pests."],"qa":[["Are all forest insects bad?","No — a tiny minority are pests; most are essential pollinators and decomposers."],["What triggers bark beetle outbreaks?","Drought-stressed, overcrowded trees plus warm winters that boost beetle survival."],["Do pesticides work in forests?","Rarely at scale — thinning, sanitation, and biocontrol are the forest tools."]]},{"title":"Emerald Ash Borer","brief":"A tiny green beetle that killed hundreds of millions of North American ash trees.","points":["Larvae chew S-shaped galleries under bark, girdling and killing ash in 2-4 years.","Adults are metallic green, half-inch beetles that emerge in summer leaving D-shaped exit holes.","It arrived from Asia in wood packaging, first detected near Detroit in 2002.","No North American ash species has natural resistance; mortality approaches 99% in infested stands."],"examples":["A city removing thousands of dead ash street trees in a single season.","Biocontrol wasps (Tetrastichus) parasitizing borer larvae under the bark."],"history":["2002: first US detection in Michigan; quarantines followed across the East and Midwest.","2010s-20s: parasitoid wasp releases established as the long-term biocontrol hope."],"uses":["Cities plan ash removal and replacement with diverse species.","Researchers breed and test resistant ash hybrids.","Campers learn: don't move firewood — it spreads the borer."],"qa":[["How do I know if my ash has it?","D-shaped exit holes, bark splits, woodpecker damage, and thinning crowns."],["Can insecticides save a tree?","Systemic treatments can protect high-value trees but must be repeated."],["What replaces ash?","Diverse native species — never plant all one species again."]]},{"title":"Bark Beetles","brief":"Tiny beetles, landscape-scale killers — how bark beetles overwhelm entire forests.","points":["Beetles bore through bark and carve egg galleries in the phloem, cutting off nutrient flow.","Blue-stain fungi they carry clog water transport, finishing what galleries start.","Pheromones coordinate mass attacks that exhaust even healthy trees' resin defenses.","Warm winters let more larvae survive, supercharging outbreaks across the West."],"examples":["Hillsides of red-needled lodgepole pine — the signature of mountain pine beetle.","A forester peeling bark to find the J-shaped galleries of Ips beetles."],"history":["Early 1900s: first western bark beetle surveys mapped periodic outbreaks.","2000s-2010s: the largest mountain pine beetle epidemic in recorded history swept BC and the US West."],"uses":["Managers thin dense stands to boost tree vigor and beetle resistance.","Salvage loggers recover value from beetle-killed timber before it rots.","Fire planners treat beetle-killed stands as heightened fuel hazards."],"qa":[["Can a tree fight off beetles?","Vigorous trees pitch them out with resin; stressed trees cannot."],["Why are outbreaks worse now?","Warmer winters, drought, and dense aging stands — a perfect storm."],["Do beetle-killed forests recover?","Yes — beetles thin the pines; aspen and young conifers reclaim the site."]]},{"title":"Dutch Elm Disease","brief":"The fungus that erased America's elm-lined streets — and the fight to bring elms back.","points":["A fungus (Ophiostoma) carried by elm bark beetles plugs the tree's water vessels.","It can also spread through root grafts between neighboring elms.","American elms — once the premier street tree — died by the tens of millions from the 1930s onward.","Resistant cultivars (Valley Forge, Princeton) now let elms return to landscapes."],"examples":["A 1930s main street shaded by cathedral-arched American elms — a scene now rare.","Sanitation crews removing a diseased elm before beetles spread spores."],"history":["1930: first US detection in Ohio; the disease swept the nation within decades.","1990s-2000s: resistant cultivars and Dutch Trig injections gave elms a second chance."],"uses":["Arborists monitor, prune, and inject high-value elms.","Cities replant with resistant cultivars and species diversity.","Breeders continue selecting for stronger resistance."],"qa":[["Can my elm be saved?","Early detection plus pruning or fungicide injection sometimes works — act fast."],["Why did elms die so fast?","Beetles spread spores efficiently, and root grafts carried fungus tree to tree."],["Are new elms safe to plant?","Resistant cultivars are far safer — and plant diverse species alongside."]]},{"title":"Forest Soils","brief":"The living ground beneath the forest — soil as the foundation of everything trees do.","points":["Forest soils form in horizons: litter, humus, topsoil, subsoil — each with distinct life and chemistry.","Mycorrhizal fungi extend root reach a hundredfold, trading nutrients for tree sugars.","Soil pH, texture, and depth determine which species thrive on a site.","Compaction from machinery crushes pore space, suffocating roots for decades."],"examples":["A soil pit showing dark topsoil over red clay — reading site quality at a glance.","White mycorrhizal threads lacing through soil around a seedling's roots."],"history":["1880s: Russian soil science founded pedology; foresters adapted it to site classification.","1990s+: mycorrhizal networks ('wood wide web') research transformed soil ecology."],"uses":["Foresters match species to soil for successful plantations.","Operators schedule harvests for dry or frozen ground to prevent compaction.","Restoration crews rebuild soils on mined and degraded lands."],"qa":[["What are mycorrhizae?","Fungal-root partnerships that massively expand nutrient uptake."],["Does logging ruin soil?","Careless logging compacts and erodes; BMPs keep damage minimal."],["Why do trees grow better on some soils?","Depth, nutrients, drainage, and pH — soil is the site's engine."]]},{"title":"Forest Hydrology","brief":"Forests and water — how trees regulate the streams the world drinks from.","points":["Canopies intercept rain; roots and litter slow it; soils store it — forests meter water release.","Forested watersheds yield cleaner, steadier streamflow than cleared land.","Transpiration recycles moisture to the atmosphere, seeding downwind rainfall.","Streamside buffers shade water, stabilize banks, and filter sediment."],"examples":["A forested headwater stream running clear after a storm that muddied farmland creeks.","Fog drip in coastal redwoods adding inches of 'hidden' precipitation."],"history":["1910s-30s: paired-watershed experiments proved forests regulate streamflow.","1970s+: clean-water laws made streamside buffers standard forestry practice."],"uses":["Water utilities protect forested watersheds as natural treatment plants.","Foresters design buffers and road drainage to keep streams clean.","Cities invest in upstream forests instead of filtration plants."],"qa":[["Do forests increase or decrease water?","They stabilize flow and improve quality; they use water but release it steadily."],["What is a streamside buffer?","An unharvested strip along water that filters runoff and shades the stream."],["Why do cities buy forestland?","Protected watersheds deliver clean water cheaper than treatment plants."]]},{"title":"Watershed Management","brief":"Managing whole landscapes for clean, reliable water — forests as water infrastructure.","points":["Watersheds are managed as units: every harvest, road, and burn affects downstream water.","Roads are the top sediment source — proper drainage and surfacing cut erosion dramatically.","Post-fire landscapes need emergency stabilization: mulching, seeding, and check dams.","Monitoring (turbidity, temperature, flow) tells managers whether practices work."],"examples":["Water bars on a skid trail diverting runoff before it reaches a creek.","A burned watershed mulched by helicopter to hold soil through winter rains."],"history":["1930s: watershed protection justified the first big federal forest purchases in the East.","1972: the Clean Water Act pushed forestry BMPs nationwide."],"uses":["Municipal water suppliers fund upstream forest stewardship.","Foresters plan operations around watershed sensitivity.","Emergency teams stabilize burned watersheds before the rains."],"qa":[["What pollutes forest streams?","Sediment from roads and harvests, mainly — controlled with BMPs."],["What is a water bar?","A diagonal ditch across a trail that sheds runoff into the woods."],["Do forests prevent floods?","They reduce peaks and erosion, though they can't stop major floods."]]},{"title":"Riparian Zones","brief":"The green ribbons along streams — the most biologically rich acres in the forest.","points":["Riparian zones host disproportionate wildlife: amphibians, birds, and mammals concentrate there.","Shade from streamside trees keeps water cool for trout and salmon.","Roots armor banks against erosion; fallen trees create fish habitat in the channel.","These zones filter nutrients and sediment before they reach water."],"examples":["A shaded trout stream running 10 degrees cooler than an exposed reach.","An eagle nest in a streamside cottonwood overlooking prime fishing."],"history":["1970s: research quantified riparian biodiversity, driving buffer regulations.","1990s+: salmon recovery made riparian restoration a priority across the Pacific Northwest."],"uses":["Foresters leave wider buffers where fish and wildlife values are high.","Restoration crews plant native trees along degraded streams.","Ranchers fence livestock out of riparian pastures."],"qa":[["How wide should a buffer be?","30-100+ feet per side depending on slope, soil, and fish presence."],["Can you harvest in riparian zones?","Light thinning sometimes; clearcutting is restricted or banned."],["Why do trout need shade?","Cold water holds more oxygen; warm water stresses and kills them."]]},{"title":"Urban Forestry","brief":"Trees where people live — managing the urban forest for health, shade, and sanity.","points":["Street trees cut summer cooling costs, filter air, and raise property values.","Urban trees face brutal conditions: compacted soil, road salt, heat, and tiny root zones.","Species diversity (no more than 10% any species) prevents the next pest catastrophe.","Inventories and management plans turn reactive trimming into planned care."],"examples":["A shaded block running 10°F cooler than a treeless street in a heat wave.","A city crew structurally pruning young trees to prevent future failures."],"history":["1872: Arbor Day launched American tree-planting culture.","1970s+: urban forestry became a profession as cities inventoried street trees."],"uses":["City foresters manage planting, pruning, and removals.","Nonprofits plant trees in underserved neighborhoods.","Utilities fund right-tree-right-place programs to cut outages."],"qa":[["What is the 10-20-30 rule?","No more than 10% one species, 20% one genus, 30% one family."],["Best street tree?","Depends on space and climate — diversity matters more than any single species."],["Do trees really cool cities?","Yes — shade plus transpiration measurably cuts heat islands."]]},{"title":"Agroforestry","brief":"Farming with trees — combining crops, livestock, and forestry on the same land.","points":["Alley cropping grows crops between rows of valuable timber or nut trees.","Silvopasture grazes livestock under thinned trees — shade plus forage plus timber.","Windbreaks cut wind erosion and protect crops, livestock, and farmsteads.","Riparian forest buffers on farms filter runoff before it reaches streams."],"examples":["Cattle grazing lush pasture beneath widely spaced pines grown for poles.","A Midwest windbreak sheltering a farmstead from blizzard winds."],"history":["1930s: Dust Bowl windbreaks planted millions of trees across the Plains.","1990s+: research centers made agroforestry a science-backed land use."],"uses":["Farmers diversify income with timber, nuts, and livestock together.","Conservationists cut farm runoff with buffers and windbreaks.","Ranchers improve animal welfare with silvopasture shade."],"qa":[["Is agroforestry profitable?","Often — stacked enterprises plus payments for conservation practices."],["What is silvopasture?","Managed grazing under trees: forage, shade, and future timber in one system."],["Do windbreaks really help crops?","Yes — reduced wind stress measurably raises yields in the sheltered zone."]]},{"title":"Old-Growth Forests","brief":"Ancient forests — complex, irreplaceable ecosystems that took centuries to build.","points":["Old growth features big trees, multiple canopy layers, snags, and abundant dead wood.","These forests host species found nowhere else: spotted owls, marbled murrelets, rare lichens.","Old-growth stores enormous carbon per acre and stabilizes it for centuries.","Once logged, true old-growth character takes 150-300+ years to return."],"examples":["A 500-year-old Douglas-fir with a trunk wider than a car.","Sunlight filtering through layered canopies onto a fern-covered nurse log."],"history":["1980s-90s: the spotted owl controversy made old-growth a national issue.","1994: the Northwest Forest Plan protected most remaining federal old growth."],"uses":["Conservationists prioritize old-growth protection and restoration.","Researchers study ancient forests as baselines for healthy ecosystems.","Ecotourism draws visitors to cathedral-like old-growth groves."],"qa":[["What counts as old growth?","Age plus structure: big trees, layered canopy, snags, and dead wood."],["Can logged forest become old growth?","Given 150-300 years without major disturbance, yes."],["Why not just plant new trees?","Plantations lack the complexity that takes centuries to develop."]]},{"title":"Boreal Forests (Taiga)","brief":"The great northern forest — a circumpolar belt of spruce, pine, and peat.","points":["The boreal spans Canada, Russia, and Scandinavia — the world's largest forest biome.","Cold, fire, and insects drive it: stand-replacing fires reset vast areas naturally.","Peatlands and permafrost beneath store more carbon than all tropical forests combined.","Species are few but abundant: spruce, pine, larch, fir, birch, and aspen dominate."],"examples":["A wildfire resetting a hundred thousand acres of black spruce in a single summer.","A peat bog holding millennia of stored carbon beneath stunted spruce."],"history":["1700s-1800s: fur trade mapped the boreal; 1900s: pulp industry moved north.","2000s+: boreal carbon storage became central to climate policy."],"uses":["Timber companies harvest pulpwood on long rotations.","Indigenous communities hunt, trap, and steward traditional territories.","Climate scientists monitor permafrost thaw and fire feedbacks."],"qa":[["What is taiga?","The Russian name for boreal forest — cold conifer forest circling the north."],["Why does the boreal matter for climate?","Its soils and peat hold colossal carbon reserves."],["How do boreal forests regenerate?","Mostly by stand-replacing fire, with serotinous cones opening in heat."]]},{"title":"Tropical Rainforests","brief":"The richest ecosystems on Earth — half the species on 6% of the land.","points":["Rainforests hold staggering diversity: a single hectare can contain 300+ tree species.","Soils are surprisingly poor — nutrients cycle rapidly through living biomass, not the ground.","Canopy layers (emergent, canopy, understory, floor) each host distinct communities.","Deforestation for cattle, soy, palm oil, and logging threatens the biome's future."],"examples":["A hectare of Amazon forest with more tree species than all of Europe.","Leaf-cutter ants farming fungus on harvested leaf fragments."],"history":["1500s-1900s: colonial extraction stripped tropical forests for rubber and timber.","1980s+: satellite monitoring exposed deforestation rates; REDD+ programs followed."],"uses":["Conservationists fight deforestation with protected areas and payments.","Indigenous peoples defend the most intact tropical forests.","Researchers catalog species faster than they vanish."],"qa":[["Why are tropical soils poor?","Heavy rain leaches nutrients; the forest stores them in living tissue."],["What is REDD+?","Payments to developing nations for keeping forests standing."],["Can rainforests recover?","Secondary forest regrows, but full diversity takes centuries."]]},{"title":"Temperate Deciduous Forests","brief":"Oak, maple, and hickory country — forests of four seasons and fall color.","points":["Broadleaf trees drop leaves in winter, conserving water and surviving frost.","Spring wildflowers race to bloom before the canopy closes overhead.","Mast (acorn and nut) cycles drive wildlife populations — boom and bust years.","Fall color comes from pigments revealed as chlorophyll breaks down."],"examples":["A hillside of sugar maples flaming orange in October.","A bumper acorn year sending deer and turkey populations soaring."],"history":["1700s-1800s: eastern forests were cleared for farms; 1900s: farms abandoned, forests returned.","Today eastern US forests are the great reforestation success story."],"uses":["Landowners manage oak and cherry for high-value hardwood timber.","Syrup producers tap the same maple stands each spring.","Millions hike, hunt, and watch fall color in these forests."],"qa":[["Why do leaves change color?","Chlorophyll drains away, revealing yellow/orange pigments; reds are made fresh."],["What is mast?","The nuts and acorns trees produce — wildlife's critical fall food."],["Are eastern forests natural?","Largely second-growth after farm abandonment — still ecologically rich."]]},{"title":"Mangrove Forests","brief":"Forests of the tides — salt-tolerant trees armoring tropical coastlines.","points":["Mangroves breathe through specialized roots (pneumatophores) in oxygen-poor mud.","They shelter juvenile fish, shrimp, and crabs — nurseries for coastal fisheries.","Dense root systems blunt storm surge and trap sediment, building land.","Mangrove soils are blue-carbon powerhouses, storing carbon for millennia."],"examples":["Prop roots arching over tidal channels at low tide.","A mangrove fringe absorbing wave energy before it hits a village."],"history":["1900s: mangroves were cleared for shrimp farms and development across the tropics.","2000s+: blue-carbon science drove global mangrove restoration."],"uses":["Coastal communities gain storm protection and fisheries.","Restoration crews replant mangroves for carbon credits.","Fisheries depend on mangrove nursery habitat."],"qa":[["How do mangroves survive salt?","Salt-excluding roots, salt-excreting leaves, and waxy coatings."],["What is blue carbon?","Carbon stored in coastal ecosystems like mangroves and seagrasses."],["Do mangroves stop hurricanes?","They can't stop them, but they sharply cut surge and wave damage."]]},{"title":"Forest Carbon Sequestration","brief":"Forests as climate infrastructure — how trees pull carbon from the sky.","points":["Trees lock CO2 into wood, roots, and soil; young fast-growing forests sequester fastest per year.","Old forests store more total carbon; the best climate strategy protects old and grows new.","Forest carbon is measured in pools: biomass, dead wood, litter, and soil organic carbon.","Permanence matters — fire, harvest, and pests can return stored carbon to the air."],"examples":["A carbon inventory crew measuring every tree in a sample plot.","A reforestation project selling verified credits to fund planting."],"history":["1997: Kyoto Protocol first counted forest carbon in climate policy.","2000s-20s: voluntary and compliance carbon markets scaled forest offsets."],"uses":["Landowners earn income from carbon credits for improved management.","Companies offset emissions by funding forest projects.","Policymakers count forests in national climate pledges."],"qa":[["Do tree-planting offsets work?","Credible ones do — with verification, additionality, and permanence safeguards."],["Plant or protect?","Both: protecting old forest keeps carbon locked; planting adds new sinks."],["What is additionality?","Proof the carbon benefit wouldn't have happened without the project."]]},{"title":"Forest Inventory and Cruising","brief":"Measuring the forest — how cruisers count trees and estimate timber value.","points":["Cruisers sample plots or strips, measuring diameter (DBH), height, and species.","Volume tables and equations convert measurements into board feet or cubic meters.","Statistical sampling lets a few hundred plots represent thousands of acres.","Modern cruises blend field plots with LiDAR and aerial imagery."],"examples":["A cruiser wrapping a diameter tape around a 30-inch oak at breast height.","A LiDAR point cloud rendering every tree in a stand from the air."],"history":["1890s: European volume tables came to American forestry schools.","2000s+: LiDAR and drones revolutionized inventory speed and detail."],"uses":["Timber buyers base bids on cruise volumes.","Managers track growth and plan harvests from inventory data.","Carbon projects verify stocks with rigorous inventories."],"qa":[["What is DBH?","Diameter at breast height — 4.5 feet above ground, the standard tree measurement."],["What is a board foot?","A 12×12×1-inch plank — 12 board feet per cubic foot of lumber."],["How accurate are cruises?","Well-designed samples estimate volume within ~10% at 95% confidence."]]},{"title":"GIS in Forestry","brief":"Digital maps that run the woods — geographic information systems for forest decisions.","points":["GIS layers stack boundaries, stands, soils, streams, and roads into one decision map.","Spatial analysis answers: where to harvest, where to burn, where habitat connects.","GPS-linked field apps let crews navigate to plots and record data on the spot.","Web maps share plans with landowners, regulators, and the public."],"examples":["A harvest map showing units, buffers, and skid trails before operations start.","A wildfire map updating containment lines in real time."],"history":["1980s: GIS moved from mainframes to forester desktops.","2000s+: GPS phones and web maps put GIS in every crew's hands."],"uses":["Planners design harvests around streams, slopes, and wildlife areas.","Fire teams map perimeters, assets, and escape routes.","Landowners view their woods and plans online."],"qa":[["What is a shapefile?","A classic GIS format storing map features and their attributes."],["Do foresters still use paper maps?","Less and less — tablets with offline maps rule the field now."],["What is LiDAR in forestry?","Laser scanning that maps terrain and canopy structure in 3D."]]},{"title":"Remote Sensing for Forests","brief":"Eyes in the sky — satellites and drones watching forests change.","points":["Multispectral imagery distinguishes species, stress, and disturbance by how leaves reflect light.","Change detection flags deforestation, fire, and beetle kill automatically across continents.","LiDAR measures canopy height and biomass; radar sees through clouds.","Drones give centimeter detail for small stands, nurseries, and post-storm damage."],"examples":["Satellite alerts pinging a ranger about new clearing in a protected forest.","A drone mapping seedling survival across a 200-acre planting."],"history":["1972: Landsat began the continuous satellite record of Earth's forests.","2010s+: free Sentinel data and cheap drones democratized forest monitoring."],"uses":["Agencies detect illegal logging and track deforestation.","Managers assess storm and fire damage without walking every acre.","Researchers measure global forest carbon from orbit."],"qa":[["Can satellites see individual trees?","High-res commercial satellites can; most forest work uses stand-level data."],["What is NDVI?","A greenness index from red and near-infrared light — the workhorse of vegetation sensing."],["Do clouds block monitoring?","Optical sensors yes; radar sees through clouds."]]},{"title":"Forest Certification (FSC/PEFC)","brief":"Proving good forestry — third-party labels for responsibly managed wood.","points":["FSC and PEFC audit forests against standards: biodiversity, worker rights, Indigenous rights.","Chain-of-custody tracking follows certified wood from stump to store shelf.","Certified products carry labels consumers recognize on lumber, paper, and furniture.","Audits are annual; major violations can suspend a certificate."],"examples":["An FSC label on lumber at the hardware store.","An auditor walking a certified forest checking buffer compliance."],"history":["1993: FSC founded after the Rio Earth Summit; PEFC followed in 1999.","2000s-10s: certification spread to hundreds of millions of acres worldwide."],"uses":["Landowners access premium markets and corporate buyers.","Retailers meet sustainability commitments with certified sourcing.","Consumers vote for good forestry with their wallets."],"qa":[["FSC vs PEFC?","FSC is performance-based and global; PEFC endorses national systems. Both are credible."],["Does certification cost landowners?","Audit costs exist, but market access often pays back."],["Is certified wood really better?","It verifies audited standards — stronger assurance than claims alone."]]},{"title":"Sustainable Forestry","brief":"Using forests without using them up — the enduring core principle.","points":["Sustained yield: harvest no more than the forest grows over the long term.","True sustainability spans timber, water, wildlife, soil, and community values together.","Certification, BMPs, and management plans turn the principle into practice.","Monitoring closes the loop — measuring whether promises hold on the ground."],"examples":["A third-generation family forest harvested twice and still fully stocked.","A management plan balancing timber income with a trout stream's health."],"history":["1905: the US Forest Service was founded on sustained-yield principles.","1990s+: sustainability expanded from timber volume to full ecosystem values."],"uses":["Family forests pass productive woods to the next generation.","Companies secure long-term supply with social license.","Societies keep forest benefits flowing indefinitely."],"qa":[["Is any logging sustainable?","Yes — when harvest stays within growth and ecosystems are protected."],["What is sustained yield?","Harvesting at or below the forest's long-term growth rate."],["Who defines sustainable?","Science, certification standards, and laws together — with public input."]]},{"title":"Clearcutting vs Selective Logging","brief":"The great harvest debate — when each system fits and what each costs.","points":["Clearcutting removes all trees: efficient, regenerates sun-loving species, but visually stark.","Selection harvests take individual trees: continuous cover, but costlier and trickier to log.","Shelterwood and seed-tree methods split the difference with partial overstory removal.","The right system depends on species ecology, owner goals, and site sensitivity."],"examples":["A clearcut regenerating to dense young pine — a future timber stand.","A selection harvest where the forest looks nearly untouched afterward."],"history":["1960s-70s: clearcutting controversies on national forests sparked reform laws.","1980s+: diversified silviculture replaced one-size-fits-all clearcutting."],"uses":["Managers match harvest method to species' light needs.","The public weighs in on visual and ecological impacts.","Loggers adapt equipment to partial-cut complexity."],"qa":[["Is clearcutting always bad?","No — it mimics natural stand-replacing disturbance for species like aspen and pine."],["Why is selection harder?","Felling among standing trees demands skill and damages more residual stems."],["Which grows more wood?","Clearcuts with planting usually maximize volume; selection maximizes other values."]]},{"title":"Thinning Operations","brief":"Giving the best trees room — intermediate harvests that improve the whole stand.","points":["Thinning removes weaker trees, concentrating growth on healthy crop trees.","Thinning from below takes suppressed trees; crown thinning opens space around dominants.","First thinnings often barely pay; later ones yield valuable poles and small logs.","Over-thinning invites windthrow and epicormic sprouting — restraint matters."],"examples":["A thinned pine stand with sunlight reaching the forest floor.","A mechanized harvester thinning rows in a 15-year-old plantation."],"history":["1930s-50s: European thinning science arrived in American plantations.","1980s+: thinning became central to plantation and restoration forestry."],"uses":["Timber growers accelerate diameter growth on final crop trees.","Wildlife managers create understory forage with light thinnings.","Fire planners thin ladder fuels around communities."],"qa":[["When to thin?","When crowns close and growth slows — often age 12-20 in plantations."],["Does thinning hurt wildlife?","Done well it boosts understory food and habitat diversity."],["What is precommercial thinning?","Early thinning too small to sell — an investment in future value."]]},{"title":"Logging Equipment","brief":"Iron in the woods — the machines that fell, skid, and load timber.","points":["Feller-bunchers cut and gather whole trees; harvesters fell, delimb, and buck at the stump.","Skidders drag logs to landings; forwarders carry cut-to-length logs on bunks.","Yarders cable-log steep ground; loaders stack and load trucks at the landing.","Mechanization cut logging injuries but demands skilled, certified operators."],"examples":["A feller-buncher shearing a pine and laying it in a neat bunch.","A forwarder threading between residual trees in a thinning."],"history":["1950s-60s: chainsaws and skidders replaced crosscuts and horses.","1990s-2000s: cut-to-length harvesters and forwarders dominated gentle terrain."],"uses":["Loggers choose systems by terrain, stand, and contract.","Mechanics keep complex machines running in remote woods.","Safety trainers certify operators on each machine type."],"qa":[["What is cut-to-length?","Processing logs to length at the stump, then forwarding them out."],["Why not use horses anymore?","Nostalgia aside, machines are faster and — with training — safer."],["Are logging jobs dangerous?","Historically very; mechanization and training cut fatality rates sharply."]]},{"title":"Forest Roads","brief":"The veins of forestry — roads that make management possible and cause most damage.","points":["Roads enable harvest, fire access, and recreation — and produce most forest sediment.","Proper drainage (ditches, culverts, water bars) keeps roads from becoming streams.","Decommissioning unneeded roads — ripping, recontouring, revegetating — heals watersheds.","Road location avoids steep slopes, wet soils, and streamside zones."],"examples":["A well-drained gravel road shedding water into the woods, not the creek.","A decommissioned road fading back into forest after ripping and planting."],"history":["1960s-70s: massive road building opened national forests to timber.","1990s-2000s: roadless protections and decommissioning reversed the tide."],"uses":["Engineers design roads for minimal erosion and cost.","Fire crews depend on road access for initial attack.","Watershed crews fix the worst sediment sources first."],"qa":[["Why are roads the big problem?","Bare running surfaces erode; ditches channel sediment straight to streams."],["What is road decommissioning?","Permanently closing and rehabilitating unneeded roads."],["Gravel or paved?","Gravel for most forest roads; paving only where traffic justifies it."]]},{"title":"Nursery Management and Tree Breeding","brief":"Where forests begin — growing millions of seedlings and breeding better trees.","points":["Nurseries grow bareroot or container seedlings matched to planting sites.","Seed orchards produce genetically improved seed: faster growth, straighter stems, disease resistance.","Tree breeding cycles take decades — selection, crossing, progeny testing, repeat.","Seed zones keep planting stock adapted to local climate."],"examples":["Greenhouse benches holding a million containerized pine seedlings.","A seed orchard of grafted plus-trees bred for growth and form."],"history":["1920s-50s: first tree improvement programs in the US South and Pacific Northwest.","1970s+: advanced-generation orchards delivered major plantation gains."],"uses":["Nurseries supply reforestation after harvest and fire.","Breeders lift plantation yields 20%+ per generation.","Seed banks preserve genetic diversity for the future."],"qa":[["Bareroot or container?","Bareroot is cheap for easy sites; containers survive better on harsh ones."],["Is tree breeding genetic engineering?","Traditional breeding selects natural variation — no gene splicing."],["What is a seed zone?","A mapped region where seed is climatically adapted — plant local."]]},{"title":"Non-Timber Forest Products","brief":"The forest's other harvest — mushrooms, berries, bark, and botanicals worth billions.","points":["Matsutake mushrooms, ginseng, and maple products anchor rural forest economies.","Harvest rules (permits, seasons, limits) keep wild collection sustainable.","Value-added processing — drying, distilling, packaging — multiplies local income.","Many NTFPs come from the same forests managed for timber."],"examples":["A forager selling chanterelles to a restaurant buyer at dawn.","A distiller bottling balsam fir essential oil from branch tips."],"history":["1990s: researchers quantified the NTFP economy, long invisible in timber stats.","2000s+: permits and certification brought order to wild harvests."],"uses":["Rural harvesters earn seasonal income from public and private forests.","Agencies permit and monitor sustainable collection.","Entrepreneurs build brands on wild forest products."],"qa":[["Do you need a permit?","Usually on public land — check local rules before picking commercially."],["Can NTFPs beat timber income?","Sometimes per acre, especially mushrooms and botanicals."],["Is wild harvest sustainable?","With seasons, limits, and monitoring — yes."]]},{"title":"Maple Syrup Production","brief":"Spring's sweet science — turning maple sap into syrup.","points":["It takes ~40 gallons of sap to make one gallon of syrup.","Taps go in when nights freeze and days thaw — the freeze-thaw pumps the sap.","Modern tubing with vacuum doubles yields over old buckets.","Reverse osmosis pre-concentrates sap, slashing boiling fuel."],"examples":["A sugarbush laced with blue tubing running downhill to a collection tank.","Steam rising from an evaporator on a cold March morning."],"history":["1600s: Indigenous peoples taught settlers sugaring; 1800s: metal spiles and evaporators.","2000s: vacuum tubing and reverse osmosis modernized the sugarbush."],"uses":["Producers manage sugarbushes as long-term forest enterprises.","Tourists flock to sugarhouses each spring.","Researchers breed sweeter, earlier-running maples."],"qa":[["When is sugaring season?","Late winter to early spring — freeze nights, thaw days."],["Does tapping hurt trees?","Proper tapping (one-two taps, rested trees) is sustainable for decades."],["What grade is darkest?","Dark/robust grades come late season — stronger maple flavor."]]},{"title":"Christmas Tree Farming","brief":"Agronomy meets forestry — growing the perfect holiday tree.","points":["Fraser fir, Douglas-fir, and Scotch pine dominate the farm-grown market.","Shearing shapes trees yearly; weed, pest, and disease control keep them marketable.","A 6-7 foot tree takes 7-10 years from planting to harvest.","Choose-and-cut farms blend agriculture with family tradition."],"examples":["Rows of sheared Fraser firs on a North Carolina mountainside.","A family sawing their tree on a frosty December choose-and-cut lot."],"history":["1900s: first US Christmas tree farms; 1950s-60s: the industry professionalized.","Today: ~15,000 US farms grow 25-30 million trees yearly."],"uses":["Growers manage intensive 7-10 year rotations.","Retailers and nonprofits run seasonal lots.","Real-tree advocates tout renewable, recyclable holidays."],"qa":[["Real or artificial?","Real trees are renewable, recyclable, and support rural economies."],["How long to grow?","7-10 years for a standard 6-7 foot tree."],["What is shearing?","Annual clipping that shapes dense, symmetrical trees."]]},{"title":"Cork Oak Harvesting","brief":"Wine's ancient closure — stripping bark without killing the tree.","points":["Cork is the bark of Quercus suber, harvested every 9-12 years.","Skilled strippers peel bark by hand with axes — a cut too deep kills the tree.","A cork oak can be harvested 12+ times over its 200-year life.","Portugal and Spain's montado/dehesa landscapes are biodiversity hotspots."],"examples":["A stripped cork oak glowing orange-red against a Portuguese hillside.","Cork planks stacked to season before punching wine stoppers."],"history":["Ancient: Romans used cork for floats and stoppers; 1700s: wine bottles standardized it.","2000s: screw caps threatened cork; premium wine kept the industry strong."],"uses":["Strippers practice a centuries-old skilled trade.","Winemakers pay premiums for natural cork closures.","Conservationists protect montado landscapes and their wildlife."],"qa":[["Does stripping hurt the tree?","Done right, no — bark regrows; bad cuts can kill."],["Why is cork special?","Light, elastic, impermeable — nature's perfect bottle seal."],["Cork vs screw cap?","Premium wines still favor cork; both have their place."]]},{"title":"Bamboo Forestry","brief":"The world's fastest timber — managing bamboo as a forest crop.","points":["Some bamboos grow 3 feet a day; culms mature for harvest in 3-5 years.","Clumping species stay put; running species need rhizome barriers.","Bamboo's strength rivals steel by weight — scaffolding, flooring, and construction.","Managed groves are clearcut on rotation like coppice forests."],"examples":["A managed moso bamboo grove harvested on a 5-year cycle.","Bamboo scaffolding wrapping a Hong Kong high-rise."],"history":["Ancient: bamboo built Asia for millennia; 2000s: engineered bamboo went global.","2010s+: bamboo flooring and panels entered mainstream green building."],"uses":["Growers harvest annual crops from permanent groves.","Builders use structural bamboo for low-carbon construction.","Manufacturers press bamboo into flooring, panels, and fiber."],"qa":[["Is bamboo a tree?","No — a giant grass, but managed like a forest crop."],["Running vs clumping?","Running spreads aggressively; clumping stays contained. Choose carefully."],["Is bamboo sustainable?","Very — rapid regrowth, no replanting, strong carbon uptake."]]},{"title":"Forest Recreation Management","brief":"Millions of visitors, one forest — managing recreation without wrecking the resource.","points":["Trail systems concentrate use: hardened trails protect surrounding habitat.","Carrying capacity — social and ecological — sets limits on crowded sites.","Fees, permits, and reservations fund maintenance and manage demand.","Leave No Trace education cuts the impacts of every visitor."],"examples":["A boardwalk carrying hikers over a fragile alpine meadow.","A permit lottery rationing access to a beloved wilderness canyon."],"history":["1964: the Wilderness Act created the recreation-protection framework.","2000s+: visitation surged; timed entry and permits spread."],"uses":["Agencies balance access with resource protection.","Outfitters guide visitors under permit systems.","Volunteers maintain thousands of miles of trail."],"qa":[["What is Leave No Trace?","Seven principles minimizing recreation impacts — pack it in, pack it out."],["Why permits?","To cap use where crowds would destroy the experience and the place."],["Do fees help?","Yes — recreation fees fund trail crews and toilets directly."]]},{"title":"National Forest Management","brief":"America's 193 million acres — multiple use on the national forests.","points":["The 1960 Multiple-Use Sustained-Yield Act: timber, water, wildlife, recreation, range.","Forest plans, revised every ~15 years, zone each forest with public input.","NEPA requires environmental analysis and public comment on major actions.","Fire, beetles, and budgets are the modern management triad."],"examples":["A forest plan meeting where loggers, hikers, and biologists hash out zones.","A NEPA analysis weighing a thinning project's effects."],"history":["1905: Forest Service founded; 1907: forest reserves renamed national forests.","1970s: NFMA and NEPA opened planning to science and the public."],"uses":["The Forest Service manages for all Americans' benefit.","Communities depend on forest jobs, water, and recreation.","Citizens shape plans through public comment."],"qa":[["What is multiple use?","Managing for timber, water, wildlife, recreation, and more together."],["Can I cut firewood?","Yes — with a permit, in designated areas."],["Who decides the plan?","The Forest Service, with science and extensive public involvement."]]},{"title":"Wildlife Habitat Management","brief":"Growing homes for wildlife — habitat as a forest product.","points":["Structure is habitat: snags for woodpeckers, down logs for salamanders, gaps for grouse.","Early successional habitat (young forest) is declining and critical for many species.","Mast trees (oak, beech, cherry) feed bears, deer, and turkeys through winter.","Corridors connect habitat patches so wildlife can move and mix."],"examples":["A retained snag hosting a pileated woodpecker nest cavity.","A 5-year-old clearcut alive with rabbits, grouse, and songbirds."],"history":["1930s: game management founded wildlife science in forests.","1970s+: endangered species law made habitat a legal management duty."],"uses":["Biologists design harvests that create needed habitat stages.","Hunters fund conservation through license dollars.","Landowners enroll in programs paying for habitat work."],"qa":[["Do clearcuts help wildlife?","Young-forest species depend on them — diversity needs all ages."],["What is a snag?","A standing dead tree — prime real estate for cavity nesters."],["How do corridors work?","Connected habitat lets animals migrate, disperse, and find mates."]]},{"title":"Forest Succession","brief":"How forests change themselves — the slow march from field to old growth.","points":["Pioneer species (aspen, pine) colonize open ground fast but need full sun.","Shade-tolerant species (maple, hemlock, fir) establish beneath and eventually dominate.","Disturbance resets the clock; without it, forests march toward climax composition.","Managers mimic or redirect succession to favor desired species."],"examples":["An old field filling with redcedar and pine within a decade.","Maple seedlings carpeting the floor beneath an oak canopy, waiting their turn."],"history":["1916: Clements formalized succession theory from prairie and forest studies.","1970s+: gap dynamics refined the model — small disturbances, not just grand stages."],"uses":["Foresters time harvests to succession's windows.","Restorationists plant to accelerate natural trajectories.","Ecologists read stand history in current composition."],"qa":[["What is climax forest?","The stable end-state community for a site's climate and soils."],["Can succession be reversed?","Disturbance — fire, harvest, storms — sets it back."],["Why do pioneers lose?","They need sun; shade-tolerant competitors overtop them."]]},{"title":"Invasive Species in Forests","brief":"Uninvited guests — non-native plants, pests, and pathogens transforming forests.","points":["Invasives like kudzu, garlic mustard, and tree-of-heaven outcompete native regeneration.","Without natural enemies, introduced pests explode: hemlock woolly adelgid, spotted lanternfly.","Early detection and rapid response (EDRR) is the only cheap stage to act.","Prevention — clean equipment, certified firewood, boat inspections — beats control."],"examples":["Kudzu smothering a forest edge in a green blanket.","A boot-brush station at a trailhead stopping weed seeds."],"history":["1800s-1900s: most forest invasives arrived with global trade.","1990s+: EDRR programs and quarantines became standard defense."],"uses":["Crews pull, cut, and treat invasive plants.","Inspectors enforce firewood and nursery quarantines.","Volunteers adopt trails and natural areas for weed patrols."],"qa":[["What is EDRR?","Early Detection Rapid Response — kill invasions while they're small."],["Why not just spray everything?","Scale, cost, and non-target damage — targeted IPM works better."],["Can invasives be eradicated?","Rarely once established; containment and asset protection are realistic."]]},{"title":"Forest Restoration","brief":"Bringing forests back — repairing damaged and degraded forest landscapes.","points":["Restoration targets a reference ecosystem: what the site was and could be again.","Techniques range from planting and invasive removal to reintroducing fire.","Success is measured against ecological criteria, not just trees planted.","Large-scale efforts (Bonn Challenge) aim to restore hundreds of millions of acres."],"examples":["Volunteers planting native seedlings on a former mine site.","A reintroduced prescribed fire returning to a long-suppressed pine savanna."],"history":["1930s: CCC planted the first great restoration wave.","2011: the Bonn Challenge launched global forest landscape restoration."],"uses":["Agencies restore public lands after fire, mining, and overuse.","Nonprofits rally volunteers for community restoration.","Companies fund restoration for carbon and water benefits."],"qa":[["Planting vs natural recovery?","Assist where seed sources or soils are gone; let nature work where it can."],["How long does restoration take?","Decades for structure; centuries for full old-growth character."],["What is the Bonn Challenge?","A global goal to restore 350 million hectares of degraded land."]]},{"title":"Community Forestry","brief":"Forests owned by the people — community forests and cooperative management.","points":["Community forests are owned or governed locally, with benefits staying local.","Cooperatives let small landowners pool timber sales, equipment, and expertise.","Urban community forestry puts neighborhoods in charge of their trees.","Revenue funds schools, trails, and local jobs — forestry as community wealth."],"examples":["A town forest funding the school budget from sustainable timber sales.","A landowner cooperative marketing certified wood together."],"history":["Early 1900s: town forests dotted New England; 2000s: the model revived.","2008: the federal Community Forest Program began funding acquisitions."],"uses":["Towns own forests for income, water, and recreation.","Cooperatives give small owners big-owner market power.","Land trusts help communities buy threatened forests."],"qa":[["What is a town forest?","Municipally owned forest managed for community benefit."],["How do cooperatives help?","Pooled volume, shared costs, better prices, professional management."],["Can communities afford forests?","Grants, bonds, and timber revenue make purchases feasible."]]},{"title":"Forest Economics","brief":"The dollars behind the trees — markets, valuation, and forest investment.","points":["Stumpage (standing timber value) varies by species, size, quality, and market distance.","Timber is a long-rotation investment: discount rates make timing critical.","Non-market values — water, carbon, recreation — increasingly enter the ledger.","Forestland has attracted institutional investors (TIMOs/REITs) seeking stable returns."],"examples":["A timber sale where oak veneer logs fetch 20x pulpwood prices.","A carbon contract paying a landowner to extend rotations."],"history":["1900s: forestry economics formalized sustained-yield finance.","1990s-2000s: TIMOs and carbon markets reshaped forest ownership."],"uses":["Investors model rotations for maximum net present value.","Appraisers value timberland for sales and taxes.","Policymakers weigh market vs non-market forest values."],"qa":[["What is stumpage?","The value of standing timber before harvest."],["Is forestry profitable?","Well-managed timberland returns steadily over decades."],["What is highest and best use?","The legally allowed use maximizing land value — not always timber."]]},{"title":"Biomass Energy from Forests","brief":"Wood to watts — forest biomass as renewable energy.","points":["Woody biomass: mill residues, thinnings, and harvest slash burned for heat and power.","Combined heat and power (CHP) plants squeeze maximum energy from each ton.","Sustainability rules require regrowth and protect sensitive forests.","Biomass is dispatchable — it burns on demand, unlike wind and solar."],"examples":["A school heated by a wood-chip boiler fed from local thinnings.","A pellet mill turning sawdust into export-grade fuel."],"history":["1970s: oil shocks sparked the first wood-energy boom.","2000s+: EU renewable mandates scaled wood pellets into a global trade."],"uses":["Mills turn waste into heat and power.","Communities heat schools and hospitals with local wood.","Policymakers debate biomass carbon accounting."],"qa":[["Is wood energy carbon neutral?","Over regrowth cycles, yes — accounting rules are hotly debated."],["What feeds biomass plants?","Residues and thinnings — not prime sawlogs."],["Pellets vs chips?","Pellets for homes and export; chips for institutional boilers."]]},{"title":"Wetlands in Forests","brief":"Forested wetlands — swamps and bottomlands of extraordinary richness.","points":["Bottomland hardwoods flood seasonally, building rich soils and wildlife abundance.","Forested wetlands filter water, store floodwater, and recharge aquifers.","They host distinct communities: prothonotary warblers, wood ducks, amphibians.","Drainage and development have erased over half of America's original wetlands."],"examples":["A cypress-tupelo swamp mirrored in black water.","Wood ducks exploding from a flooded oak bottom at dawn."],"history":["1970s: Clean Water Act protections slowed wetland losses.","1980s+: 'no net loss' policy and mitigation banking reshaped development."],"uses":["Regulators permit impacts only with mitigation.","Mitigation bankers restore wetlands for credit sales.","Duck hunters fund wetland conservation at scale."],"qa":[["What is mitigation banking?","Restoring wetlands to sell credits offsetting permitted impacts elsewhere."],["Can you log swamps?","Carefully, with seasonal and equipment restrictions — or not at all."],["Why save swamps?","Flood control, water quality, and wildlife — cheap compared to engineered fixes."]]},{"title":"Forest Policy and Law","brief":"The rules of the woods — laws shaping how forests are managed.","points":["Property rights anchor forestry: owners generally choose management, within regulations.","Water, wildlife, and burning laws constrain practices near streams, species, and smoke.","Tax programs (current-use valuation) keep working forests from becoming subdivisions.","Public forest law (NFMA, NEPA) mandates planning, science, and public voice."],"examples":["A landowner enrolling in current-use tax to keep the family forest intact.","A NEPA comment period drawing 10,000 voices on a forest plan."],"history":["1891: Forest Reserve Act; 1960s-70s: the great environmental law wave.","2000s+: state and federal laws adapted to carbon, fire, and climate."],"uses":["Landowners navigate taxes, permits, and cost-share programs.","Agencies implement plans under public scrutiny.","Advocates shape law through courts and legislatures."],"qa":[["What is current-use tax?","Taxing forestland at its forestry value, not development value."],["What does NEPA require?","Environmental analysis and public comment on major federal actions."],["Can laws stop all logging?","No — and they don't try; they set standards for how it's done."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-forestry-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('forestry',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();